// Plugin by MySquadStats.com - @psg_ignis
// DO NOT EDIT THIS FILE WITHOUT CONSULTING MYSQUADSTATS

import axios from 'axios';
import crypto from 'crypto';
import { fileURLToPath } from 'url';
import path from 'path';
import fs from 'fs';

import BasePlugin from './base-plugin.js';

const currentVersion = 'v6.0.4';
let updated = false;
// A newer version whose download could not be written to the plugin file
let unwritableUpdate = null;

// How long a call to MySquadStats may take before the plugin stops waiting
// for its answer.
const API_TIMEOUT = 30 * 1000;
// The API takes longer with big admin lists, and with a round end, which
// waits for the server's player list being handled (close to a minute when
// the database is slow, as after an outage).
const ADMINS_API_TIMEOUT = 2 * 60 * 1000;
// How long a download from GitHub or a remote admin list may take.
const DOWNLOAD_TIMEOUT = 30 * 1000;
// How many more times a round end is sent when the API answers it with an
// Error. The API closes a match only once, so sending it again is safe.
const MATCH_END_RETRIES = 3;
// A match that GET /matches finds, or that a new match sent again creates, is
// taken as the game's match only if it is on the game's layer and started at
// most this long before or after the game did. Both starts are the game's
// NEW_GAME time, which the database keeps in whole seconds. Any other match is
// another game's, such as the match before, left open.
const MATCH_START_SLACK = 5 * 1000;
// An open match that started more than this long before the time it would be
// used for is never used: the API closes the matches left open only when
// they started in the 24 hours before a new match, so an older one, such as
// one left open before a long gap, can stay open for good, and GET /matches
// gives it whenever no newer match is open. Only a seed or training layer's
// game can last this long: after a restart during one, its own match is not
// taken either, until the next game.
const OPEN_MATCH_MAX_AGE = 24 * 60 * 60 * 1000;
// A saved request that gets a 502 this many times while MySquadStats answers
// pings is dropped: the request itself is what fails, and it would hold up
// every request saved after it for good. A saved new match counts the times
// it gets no answer too, and a moved wound, death or revive the times the API
// finds no match for it (see retryFailedRequests).
const RETRY_502_LIMIT = 10;
// The requests sent again are removed from the retry files in batches: after
// this many, or after this long, and at the end of each pass. Each answered
// request is also noted at once in a small file, so that a stop between two
// removals sends again only the request that was being sent (a wound, death
// or revive sent again is saved twice; see answeredFilePath). New matches and
// round ends are removed as soon as they are answered, and the batch is
// removed before one is sent, as these can take a while to be answered.
const RETRY_REMOVE_BATCH = 50;
const RETRY_REMOVE_INTERVAL = 2 * 1000;
// The requests that carry the match they were made in
const EVENT_DATA_TYPES = ['wounds', 'deaths', 'revives'];

export default class MySquadStats extends BasePlugin {
  static get description() {
    return 'The <code>MySquadStats.com</code> plugin will log various server statistics and events to a central database for player stat tracking.';
  }

  static get defaultEnabled() {
    return false;
  }

  static get optionsSpecification() {
    return {
      accessToken: {
        required: true,
        description: 'The access token to use for the database.',
        default: 'YOUR_ACCESS_TOKEN', // DO NOT MODIFY THIS - Change this in config.json!
      },
      allowInGameStatsCommand: {
        required: false,
        description:
          'Allow players to check their stats in-game via an AdminWarn.',
      },
      allowSimpleStatsCommand: {
        required: false,
        description:
          'Allow players to check their stats in-game via !stats as well as !mss stats.',
      },
    };
  }

  constructor(server, options, connectors) {
    super(server, options, connectors);

    this.onChatCommand = this.onChatCommand.bind(this);
    this.onRoundEnded = this.onRoundEnded.bind(this);
    this.onNewGame = this.onNewGame.bind(this);
    this.onPlayerConnected = this.onPlayerConnected.bind(this);
    this.onPlayerWounded = this.onPlayerWounded.bind(this);
    this.onPlayerDied = this.onPlayerDied.bind(this);
    this.onPlayerRevived = this.onPlayerRevived.bind(this);
    this.isProcessingFailedRequests = false;
    this.isGettingPlayers = false;
    this.connectedPlayers = {};
    // The match of the game being played, or null when there is none
    this.match = null;
    // Counts new games, so an older one's match never replaces a newer one's
    this.gameCount = 0;
    // When the game being played started, and its layer, once a new game has
    // been seen
    this.gameStartTime = null;
    this.gameLayerClassname = null;
    // The game's new match, kept to send again while the game has no match
    // (see recoverMatch)
    this.matchPost = null;
    // Whether the open match is still to be asked for, as MySquadStats did
    // not answer at mount (see pingMySquadStats)
    this.mountMatchUnknown = false;
    // An earlier game's match that the API gave as the server's open match
    // (see noteEarlierMatch), or null
    this.earlierMatch = null;
    // Killstreaks
    this.trackedKillstreaks = {};
    // The match that ended and its round end, from the round end until the
    // next game (see killstreakTarget)
    this.killstreakEndedMatch = null;
    this.killstreakWounded = this.killstreakWounded.bind(this);
    this.killstreakDied = this.killstreakDied.bind(this);
    this.killstreakRoundEnded = this.killstreakRoundEnded.bind(this);
    this.killstreakNewGame = this.killstreakNewGame.bind(this);
    this.killstreakDisconnected = this.killstreakDisconnected.bind(this);
  }

  async prepareToMount() {}

  async mount() {
    // The requests earlier versions saved to send again are taken first, so
    // the match checks below see the round ends among them
    this.takeLegacyRetryFiles();

    // Post Request to create Server in API
    let dataType = 'servers';
    const serverData = {
      name: this.server.serverName,
      version: currentVersion,
    };
    const response = await postDataToAPI(
      dataType,
      serverData,
      this.options.accessToken
    );
    this.verbose(1, `Mount-Server | ${response.status} | ${response.message}`);

    // The game being played started before the plugin did: its start is not
    // known, but its layer is when SquadJS knows the current layer, so an
    // open match on another layer is not taken (see isMatchOfGame)
    this.gameLayerClassname = this.server.currentLayer?.classname ?? null;

    // GET Request to get Match Info from API
    dataType = 'matches';
    const matchResponse = await getDataFromAPI(
      dataType,
      this.options.accessToken
    );
    // GET /matches answers with an empty body when the server has no open
    // match
    const openMatch = matchFrom(matchResponse);
    if (openMatch) {
      this.takeMatch(openMatch, this.gameCount, 'Mount-Match');
    } else {
      // Any other answer, such as a 502, does not say
      this.mountMatchUnknown = matchResponse !== '';
      this.verbose(
        1,
        `Mount-Match | No open match | ${matchResponse.message || 'Waiting for the next game.'}`
      );
    }

    // Get currently connected players
    const players = await this.server.rcon.getListPlayers();
    // For each player, get their MSS ID
    for (const player of players) {
      if (!player.steamID) continue;
      // Patch Request to create Player in API
      const dataType = 'players';
      const playerData = {
        eosID: player.eosID,
        steamID: player.steamID,
        lastName: player.name,
        lastIP: player.ip,
      };
      const playerResponse = await patchDataInAPI(
        dataType,
        playerData,
        this.options.accessToken
      );
      if (playerResponse.status === 'Error') {
        this.verbose(
          1,
          `Mount-Player | ${playerResponse.status} | ${playerResponse.message}`
        );
      } else if (playerResponse.status === 'Success') {
        // Add to connected Players
        this.connectedPlayers[player.steamID] = {
          mssID: playerResponse.data.mssID,
        };
      }
    }

    // Subscribe to events
    this.server.on(`CHAT_COMMAND:mss`, this.onChatCommand);
    this.server.on(`CHAT_COMMAND:stats`, this.onChatCommand);
    this.server.on('ROUND_ENDED', this.onRoundEnded);
    this.winningTeamTracking = {};
    this.server.on('NEW_GAME', this.onNewGame);
    this.server.on('PLAYER_CONNECTED', this.onPlayerConnected);
    this.server.on('PLAYER_WOUNDED', this.onPlayerWounded);
    this.server.on('PLAYER_DIED', this.onPlayerDied);
    this.server.on('PLAYER_REVIVED', this.onPlayerRevived);
    this.server.on('PLAYER_WOUNDED', this.killstreakWounded);
    this.server.on('PLAYER_DIED', this.killstreakDied);
    this.server.on('ROUND_ENDED', this.killstreakRoundEnded);
    this.server.on('NEW_GAME', this.killstreakNewGame);
    this.server.on('PLAYER_DISCONNECTED', this.killstreakDisconnected);
    // Check for updates in GitHub. Not awaited, so it must not throw.
    this.checkVersion().catch((error) =>
      this.verbose(1, `Version check failed: ${error.message}`)
    );
    // Every 1 minute, ping MySquadStats
    this.pingInterval = setInterval(this.pingMySquadStats.bind(this), 60000);
    // Every 30 minutes, send Admins and Whitelisters to MySquadStats
    this.getAdminsInterval = setInterval(this.getAdmins.bind(this), 1800000);
    this.getPlayersInterval = setInterval(this.getPlayers.bind(this), 60000);
  }

  async unmount() {
    this.server.removeEventListener(`CHAT_COMMAND:mss`, this.onChatCommand);
    this.server.removeEventListener(`CHAT_COMMAND:stats`, this.onChatCommand);
    this.server.removeEventListener('ROUND_ENDED', this.onRoundEnded);
    this.server.removeEventListener('NEW_GAME', this.onNewGame);
    this.server.removeEventListener('PLAYER_CONNECTED', this.onPlayerConnected);
    this.server.removeEventListener('PLAYER_WOUNDED', this.onPlayerWounded);
    this.server.removeEventListener('PLAYER_DIED', this.onPlayerDied);
    this.server.removeEventListener('PLAYER_REVIVED', this.onPlayerRevived);
    this.server.removeEventListener('PLAYER_WOUNDED', this.killstreakWounded);
    this.server.removeEventListener('PLAYER_DIED', this.killstreakDied);
    this.server.removeEventListener('ROUND_ENDED', this.killstreakRoundEnded);
    this.server.removeEventListener('NEW_GAME', this.killstreakNewGame);
    this.server.removeEventListener(
      'PLAYER_DISCONNECTED',
      this.killstreakDisconnected
    );
    clearInterval(this.pingInterval);
    clearInterval(this.getAdminsInterval);
    clearInterval(this.getPlayersInterval);
  }

  // Takes the requests that earlier versions saved to send again into this
  // server's retry files (see claimLegacyRetryFiles), and names the retry
  // files of other access tokens, which are left alone.
  takeLegacyRetryFiles() {
    const log = (message) => this.verbose(1, `Mount-Retry | ${message}`);
    try {
      const { taken, droppedLists } = claimLegacyRetryFiles(
        this.options.accessToken,
        log
      );
      if (taken > 0 || droppedLists > 0) {
        log(
          `Took ${taken} request${taken === 1 ? '' : 's'} saved by an earlier version to send again, and dropped ${droppedLists} saved player list${droppedLists === 1 ? '' : 's'}.`
        );
      }
    } catch (error) {
      log(
        `Could not take the requests saved by an earlier version: ${error.message}`
      );
    }
    const others = otherRetryFiles(this.options.accessToken);
    if (others.length > 0) {
      log(
        `Requests saved under another access token are left for the server that uses it: ${others.join(', ')}. If this server's access token was changed, see the README to send them.`
      );
    }
  }

  async checkVersion(latestVersion) {
    const owner = 'Ignis-Bots';
    const repo = 'SquadJS-My-Squad-Stats';

    if (!latestVersion) {
      try {
        latestVersion = await getLatestVersion(owner, repo);
      } catch (error) {
        this.verbose(
          1,
          `Error retrieving the latest version of ${repo} from ${owner}:`,
          error
        );
      }
    }

    const __DataDirname = fileURLToPath(import.meta.url);
    // Create Update Cleared File
    const updateClearedFilePath = path.join(
      __DataDirname,
      '..',
      '..',
      'MySquadStats_Data',
      'update-cleared.json'
    );

    // Create the directory if it does not exist
    const dir = path.dirname(updateClearedFilePath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }

    // Create Update Cleared if not exists with cleared: false
    if (!fs.existsSync(updateClearedFilePath)) {
      const data = JSON.stringify({ cleared: false }, null, 2);
      fs.writeFileSync(updateClearedFilePath, data);
    }

    let updateCleared;
    try {
      updateCleared = JSON.parse(
        fs.readFileSync(updateClearedFilePath, 'utf8')
      );
    } catch (error) {
      // A file that cannot be read, such as one whose write was cut short,
      // counts as cleared, so the saved requests are kept. It is written
      // again.
      this.verbose(
        1,
        `Could not read ${updateClearedFilePath}: ${error.message}`
      );
      updateCleared = { cleared: true };
      fs.writeFileSync(updateClearedFilePath, JSON.stringify(updateCleared));
    }
    if (!updateCleared?.cleared) {
      // The first start after an update. The requests saved to send again
      // are kept, as this version sends those saved by earlier versions too
      // (see takeLegacyRetryFiles).

      // Create/Update the update-cleared.json file
      fs.writeFileSync(
        updateClearedFilePath,
        JSON.stringify({ cleared: true })
      );
    }

    // No version to compare with, as when GitHub could not be reached
    if (typeof latestVersion !== 'string') {
      this.verbose(1, `Unable to check for updates in ${repo}.`);
      return;
    }

    const comparisonResult = await compareVersions(
      currentVersion,
      latestVersion
    );

    if (
      comparisonResult < 0 &&
      !updated &&
      unwritableUpdate === latestVersion
    ) {
      this.verbose(
        1,
        `A new version of ${repo} (${latestVersion}) is available, but the plugin file could not be written. Please update it by hand.`
      );
    } else if (comparisonResult < 0 && !updated) {
      this.verbose(1, `A new version of ${repo} is available. Updating...`);

      const updatedCodeUrl = `https://raw.githubusercontent.com/${owner}/${repo}/${latestVersion}/squad-server/plugins/my-squad-stats.js`;

      // Download the updated code
      let updatedCode;
      try {
        const response = await axios.get(updatedCodeUrl, {
          timeout: DOWNLOAD_TIMEOUT,
        });
        updatedCode = response.data;
      } catch (error) {
        this.verbose(
          1,
          `Error downloading the updated plugin for ${repo}:`,
          error
        );
        return;
      }

      const __dirname = path.dirname(fileURLToPath(import.meta.url));
      const filePath = path.join(__dirname, 'my-squad-stats.js');
      try {
        fs.writeFileSync(filePath, updatedCode);
      } catch (error) {
        // Not downloaded again for this version: the file stays as it was
        unwritableUpdate = latestVersion;
        this.verbose(
          1,
          `Could not write the update of ${repo} to ${filePath}: ${error.message}. Please update it by hand.`
        );
        return;
      }

      // Set the update-cleared.json file to false
      fs.writeFileSync(
        updateClearedFilePath,
        JSON.stringify({ cleared: false })
      );

      updated = true;
      this.verbose(
        1,
        `Successfully updated ${repo} to version ${latestVersion}. Please restart the Node.js process to apply the changes.`
      );
    } else if (comparisonResult > 0) {
      this.verbose(
        1,
        `You are running a newer version of ${repo} than the latest version.\nThis likely means you are running a pre-release or beta version.\nYour Current Version: ${currentVersion} Latest Version: ${latestVersion}\nhttps://github.com/${owner}/${repo}/releases`
      );
    } else if (comparisonResult === 0) {
      this.verbose(1, `You are running the latest version of ${repo}.`);
    } else {
      this.verbose(1, `Unable to check for updates in ${repo}.`);
    }
    return;
  }

  async pingMySquadStats() {
    this.verbose(1, 'Pinging MySquadStats...');
    if (this.isProcessingFailedRequests) {
      this.verbose(1, 'Already processing failed requests...');
      return;
    }
    this.isProcessingFailedRequests = true;

    // Whatever happens below, the next ping can retry again
    try {
      const dataType = 'ping';
      const response = await getDataFromAPI(dataType, this.options.accessToken);
      if (response.message === 'pong') {
        this.verbose(1, 'Pong! MySquadStats is up and running.');

        const serverPluginVersion = response.data?.serverPluginVersion;
        // Check Version. Not awaited, so it must not throw.
        if (typeof serverPluginVersion === 'string') {
          this.checkVersion(serverPluginVersion).catch((error) =>
            this.verbose(1, `Version check failed: ${error.message}`)
          );
        }

        // Without a match, as when the new game's match could not be
        // created, find or create it first, so the events sent from now on
        // carry it. Only for a game the plugin saw start: then only a match
        // on its layer that started with it is taken (see isMatchOfGame).
        // For a game that started before the plugin did, only the layer and
        // the match's age are checked, and the server's open match can still
        // be the one before, whose round end is saved to send below.
        if (!this.match && this.gameStartTime) {
          await this.recoverMatch();
        } else if (!this.match && this.mountMatchUnknown) {
          // MySquadStats did not answer at mount: the open match is asked
          // for now, before the saved requests are sent, as mount would have
          // done, so that this game's wounds, deaths and revives saved with
          // no match go out with it (see gameMatch). The match before, whose
          // round end is saved, is not taken (see takeMatch).
          if ((await this.findMatch('Ping-Match')) !== undefined) {
            this.mountMatchUnknown = false;
          }
        }

        const completed = await retryFailedRequests(
          this.options.accessToken,
          (message) => this.verbose(1, message),
          (request, answer) => this.onRetryAnswer(request, answer),
          () => this.gameMatch(),
          this.earlierMatch
        );
        if (completed) this.verbose(1, completed);

        // For a game that started before the plugin did, the match is asked
        // for once the saved requests are sent, which may have closed the
        // match before and created this game's
        if (!this.match && !this.gameStartTime) {
          await this.findMatch('Ping-Match');
        }
      }
    } catch (error) {
      this.verbose(1, `Ping-MySquadStats | Error | ${error.message}`);
    } finally {
      this.isProcessingFailedRequests = false;
    }
    return;
  }

  // Called with each answer to a saved request sent again (see
  // pingMySquadStats). For a game the plugin saw start, a new match sent
  // again is taken as soon as it is created, so live events stop going out
  // with no match during a long replay. For a game that started before the
  // plugin did, no match is taken here; and when a request sent again closes
  // the match in use, it is let go, so the match is asked for again after
  // the replay. The match in use is then the match before, taken at mount
  // or at the first ping: a round end sent again that names it closes it,
  // and so does a new match sent again that started after it, as the API
  // closes the matches left open that started before a new one.
  onRetryAnswer(request, answer) {
    if (request.dataType !== 'matches') return;
    if (this.gameStartTime) {
      if (request.method === 'post') {
        this.takeMatch(matchFrom(answer), this.gameCount, 'Retry-Match');
      }
      return;
    }
    if (!this.match) return;
    const created = request.method === 'post' ? matchFrom(answer) : null;
    const ended =
      request.method === 'patch' &&
      answer?.status === 'Success' &&
      request.data?.match === this.match.id;
    const replaced =
      created !== null &&
      created.id !== this.match.id &&
      new Date(this.match.startTime).getTime() <
        new Date(created.startTime).getTime();
    if (!ended && !replaced) return;
    this.verbose(
      1,
      `Retry-Match | Match ${this.match.id} has ended. Asking for the open match after the replay.`
    );
    this.match = null;
  }

  // Takes a match as the match of the game given, unless a newer game has
  // started, the game has its match already, or the match is another game's
  // (see isMatchOfGame). Returns whether it was taken.
  takeMatch(match, game, label) {
    if (!match || game !== this.gameCount || this.match) return false;
    if (!isMatchOfGame(match, this.gameStartTime, this.gameLayerClassname)) {
      this.noteEarlierMatch(match);
      this.verbose(
        1,
        `${label} | No match | Match ${match.id} is another game's.`
      );
      return false;
    }
    // For a game that started before the plugin did, an open match whose
    // round end is saved to send again is the match before, which that
    // round end closes. The match is asked for again once the saved
    // requests are sent (see pingMySquadStats), as it is when the saved
    // round ends cannot be read now.
    const ended =
      !this.gameStartTime && isRoundEndSaved(match, this.options.accessToken);
    if (ended) {
      this.noteEarlierMatch(match);
      this.verbose(
        1,
        `${label} | No match | Match ${match.id} has ended: its round end is saved to send again.`
      );
      return false;
    }
    if (ended === null) {
      this.verbose(
        1,
        `${label} | No match | Match ${match.id} is not taken for now: the saved round ends cannot be read.`
      );
      return false;
    }
    this.match = match;
    // The game's new match saved to send again would now create its match a
    // second time
    try {
      removeSavedNewMatch(
        match,
        this.matchPost?.retryId ?? null,
        this.options.accessToken
      );
    } catch (error) {
      this.verbose(
        1,
        `${label} | Could not remove the saved new match: ${error.message}`
      );
    }
    this.matchPost = null;
    this.verbose(1, `${label} | Success | Using match ${match.id}.`);
    return true;
  }

  // Notes an open match that takeMatch did not take as an earlier game's
  // match left open, as when SquadJS restarted during that game while
  // MySquadStats was down: one that started before the game being played,
  // or any such match while that game's start is not known. The wounds,
  // deaths and revives of its game saved with no match are then sent with
  // it (see earlierMatchWindow).
  noteEarlierMatch(match) {
    const start = new Date(match.startTime).getTime();
    if (Number.isNaN(start)) return;
    let until = null;
    if (this.gameStartTime) {
      until = new Date(this.gameStartTime).getTime();
      if (Number.isNaN(until) || start >= until - MATCH_START_SLACK) return;
    }
    this.earlierMatch = { id: match.id, startTime: match.startTime, until };
  }

  // The match of the game being played, and since when it is: the game's
  // start when the plugin saw it, or else the match's own start, less
  // MATCH_START_SLACK. Null when the plugin holds no match of the game. A
  // wound, death or revive saved with no match since then is sent with it
  // (see dataToSend).
  gameMatch() {
    if (!this.match) return null;
    if (this.gameStartTime) {
      return isMatchOfGame(
        this.match,
        this.gameStartTime,
        this.gameLayerClassname
      )
        ? { id: this.match.id, since: this.gameStartTime }
        : null;
    }
    const start = new Date(this.match.startTime).getTime();
    return Number.isNaN(start)
      ? null
      : { id: this.match.id, since: start - MATCH_START_SLACK };
  }

  // Asks the API for the server's open match and takes it as this game's
  // match (see takeMatch). Returns the match taken; null when the API
  // answered that the server has no open match of this game; or undefined
  // when it could not say (an Error, or no answer), or a newer game has
  // started meanwhile.
  async findMatch(label) {
    const game = this.gameCount;
    const response = await getDataFromAPI('matches', this.options.accessToken);
    if (game !== this.gameCount) return undefined;
    if (this.match) return this.match;
    const match = matchFrom(response);
    if (!match) {
      this.verbose(
        1,
        `${label} | No match | ${response.message || 'The server has no open match.'}`
      );
      // GET /matches answers with an empty body when the server has no open
      // match
      return response === '' ? null : undefined;
    }
    return this.takeMatch(match, game, label) ? match : null;
  }

  // For a game the plugin saw start that has no match: asks the API for it,
  // as it may have been created although its answer was lost; and when the
  // API answers that it has none, sends the game's new match again, at most
  // once a ping. A new match saved to send again after a 502 is left to the
  // requests sent again.
  async recoverMatch() {
    const game = this.gameCount;
    const found = await this.findMatch('Ping-Match');
    if (found !== null) return;
    const post = this.matchPost;
    if (!post || post.game !== game || game !== this.gameCount || this.match) {
      return;
    }
    if (
      post.retryId &&
      isSavedForRetry('post', post.retryId, this.options.accessToken)
    ) {
      return;
    }

    const response = await postDataToAPI(
      'matches',
      post.data,
      this.options.accessToken,
      { saveForRetry: false }
    );
    const match = matchFrom(response);
    if (!match) {
      this.verbose(
        1,
        `Ping-Post-Match | ${response.status} | ${response.message}`
      );
      return;
    }
    this.takeMatch(match, game, 'Ping-Post-Match');
  }

  async getAdmins() {
    this.verbose(1, 'Getting Admins...');
    const adminLists = this.server.options.adminLists;
    const groups = {};
    const admins = {};
    const __dirname = fileURLToPath(import.meta.url);

    for (const [idx, list] of adminLists.entries()) {
      let data = '';
      try {
        switch (list.type) {
          case 'remote': {
            const resp = await axios({
              method: 'GET',
              url: `${list.source}`,
              timeout: DOWNLOAD_TIMEOUT,
            });
            data = resp.data;
            break;
          }
          case 'local': {
            const listPath = path.resolve(__dirname, '../../../', list.source);
            if (!fs.existsSync(listPath))
              throw new Error(`Could not find Admin List at ${listPath}`);
            data = fs.readFileSync(listPath, 'utf8');
            break;
          }
          default:
            throw new Error(`Unsupported AdminList type:${list.type}`);
        }
      } catch (error) {
        this.verbose(
          1,
          `Error fetching ${list.type} admin list: ${list.source}`,
          error
        );
      }

      const groupRgx =
        /(?<=^Group=)(?<groupID>.*?):(?<groupPerms>.*?)(?=(?:\r\n|\r|\n|\s+\/\/))/gm;
      const adminRgx =
        /(?<=^Admin=)(?<adminID>\d{17}|[a-f0-9]{32}):(?<groupID>\S+)(?:.*@(?<discordUsername>\S*))?/gm;

      for (const m of data.matchAll(groupRgx)) {
        groups[`${idx}-${m.groups.groupID}`] = m.groups.groupPerms
          .split(',')
          .map((perm) => perm.trim());
      }
      for (const m of data.matchAll(adminRgx)) {
        try {
          const group = groups[`${idx}-${m.groups.groupID}`];
          const perms = {};
          for (const groupPerm of group) perms[groupPerm.toLowerCase()] = true;

          const adminID = m.groups.adminID;
          const discordUsername = m.groups.discordUsername || null;

          if (adminID in admins) {
            admins[adminID] = Object.assign(admins[adminID], perms, {
              discordUsername,
            });
            this.verbose(
              3,
              `Merged duplicate Admin ${adminID} to ${Object.keys(
                admins[adminID]
              )}`
            );
          } else {
            admins[adminID] = Object.assign(perms, { discordUsername });
            this.verbose(
              3,
              `Added Admin ${adminID} with ${Object.keys(perms)}`
            );
          }
        } catch (error) {
          this.verbose(
            1,
            `Error parsing admin group ${m.groups.groupID} from admin list: ${list.source}`,
            error
          );
        }
      }
    }
    this.verbose(1, `${Object.keys(admins).length} Admins/Reserve loaded...`);

    // Post Request to Admins API
    const dataType = 'admins';
    const response = await postDataToAPI(
      dataType,
      admins,
      this.options.accessToken
    );

    if (response.status === 'Error') {
      this.verbose(
        1,
        `Admins-Admins | ${response.status} | ${response.message}`
      );
    } else {
      this.verbose(
        1,
        `Admins-Admins | ${response.status} | ${response.message}`
      );
    }
    return;
  }

  async getPlayers() {
    // A list still being sent (a slow API) is not sent twice over: the next
    // list follows within a minute.
    if (this.isGettingPlayers) {
      this.verbose(1, 'Still sending the last player list...');
      return;
    }
    this.isGettingPlayers = true;
    try {
      await this.sendPlayers();
    } catch (error) {
      this.verbose(1, `Players-Players | Error | ${error.message}`);
    } finally {
      this.isGettingPlayers = false;
    }
    return;
  }

  async sendPlayers() {
    this.verbose(1, 'Getting Players...');
    const publicSlots = this.server.publicSlots;
    const reserveSlots = this.server.reserveSlots;
    const publicQueue = this.server.publicQueue;
    const reserveQueue = this.server.reserveQueue;

    const players = await this.server.rcon.getListPlayers();
    // Older SquadJS answers with the squads, newer SquadJS with
    // [squads, tickets]
    const squadsAnswer = await this.server.rcon.getSquads();
    let squads =
      Array.isArray(squadsAnswer) && Array.isArray(squadsAnswer[0])
        ? squadsAnswer[0]
        : squadsAnswer;
    // When the list was read. The API ignores it for now.
    const capturedAt = new Date().toISOString();

    // Ensure squads is always an array
    if (!Array.isArray(squads)) {
      this.verbose(
        1,
        'No squads found or error fetching squads, initializing as empty array.'
      );
      squads = [];
    }

    // Get Match ID
    const matchID = this.match && this.match.id ? this.match.id : null;

    // Initialize an object to hold teams
    const teams = {
      1: {
        teamID: '1',
        teamName: 'Team 1',
        matchID,
        capturedAt,
        publicSlots,
        reserveSlots,
        publicQueue,
        reserveQueue,
        squads: [
          {
            squadID: '0',
            squadName: 'Unassigned',
            teamID: '1',
            isCommandSquad: false,
            players: [],
          },
        ],
      },
      2: {
        teamID: '2',
        teamName: 'Team 2',
        matchID,
        capturedAt,
        publicSlots,
        reserveSlots,
        publicQueue,
        reserveQueue,
        squads: [
          {
            squadID: '0',
            squadName: 'Unassigned',
            teamID: '2',
            isCommandSquad: false,
            players: [],
          },
        ],
      },
    };

    // Iterate over each squad
    for (const squad of squads) {
      // Add the squad to the team
      if (teams[squad.teamID]) {
        // Build players array with mssID for each player in the squad
        const squadPlayers = [];
        for (const player of players) {
          if (
            player.squadID === squad.squadID &&
            player.teamID === squad.teamID
          ) {
            const playerMSSID = await this.getPlayerMSSID(player.steamID);
            squadPlayers.push({
              ...player,
              mssID: playerMSSID,
            });
          }
        }
        teams[squad.teamID].squads.push({
          ...squad,
          isCommandSquad: squad.squadName === 'Command Squad',
          players: squadPlayers,
        });
      } else {
        this.verbose(
          1,
          `Unknown teamID: ${squad.teamID}, squadID: ${squad.squadID}`
        );
      }
    }

    // Add unassigned players to the "Unassigned" squad
    for (const player of players) {
      if (teams[player.teamID]) {
        if (player.squadID === null) {
          const playerMSSID = await this.getPlayerMSSID(player.steamID);
          player.mssID = playerMSSID;
          teams[player.teamID].squads[0].players.push(player);
        }
      } else {
        this.verbose(
          1,
          `Unknown teamID: ${player.teamID}, playerID: ${player.id}`
        );
      }
    }

    // Update the size of the "Unassigned" squad
    for (const teamID in teams) {
      const unassignedSquad = teams[teamID].squads[0];
      unassignedSquad.size = unassignedSquad.players.length;
    }

    // Convert the teams object to an array
    const playersData = Object.values(teams);

    // POST serversPlayers to API. A list that gets a 502 is not saved to send
    // again: a newer list follows within a minute.
    const dataType = 'serversPlayers';
    const response = await postDataToAPI(
      dataType,
      playersData,
      this.options.accessToken,
      { saveForRetry: false }
    );

    if (response.status === 'Error') {
      this.verbose(
        1,
        `Players-Players | ${response.status} | ${response.message}`
      );
    }
    return;
  }

  async onChatCommand(info) {
    // SquadJS gives no player when it cannot find the sender: there is no
    // one to answer
    if (!info.player?.steamID) return;

    // Get the message
    const message = info.message.toLowerCase();

    let simpleStatsCommand = false;
    if (
      this.options.allowSimpleStatsCommand === true &&
      info.raw.toLowerCase().endsWith('!stats')
    ) {
      simpleStatsCommand = true;
    }

    // Help Commands
    if (
      (message === 'help' ||
        message === 'commands' ||
        message === 'cmds' ||
        message === 'h' ||
        message.length === 0) &&
      simpleStatsCommand === false
    ) {
      let warningMessage = `Commands:`;
      if (this.options.allowInGameStatsCommand === true) {
        warningMessage += `\n!mss stats - Check your stats\nLogin to MySquadStats.com to Link`;
      } else {
        warningMessage += `\n!mss stats - Check your stats\nThis Server has disabled the in-game stats command.\nCheck your stats at MySquadStats.com`;
      }
      await this.server.rcon.warn(info.player.steamID, warningMessage);
    }

    if (message.startsWith('link')) {
      await this.server.rcon.warn(
        info.player.steamID,
        `Linking is now done on our website.\nLogin to MySquadStats.com to Link.`
      );
    } else if (message === 'stats' || simpleStatsCommand === true) {
      if (this.options.allowInGameStatsCommand === false) {
        return this.server.rcon.warn(
          info.player.steamID,
          `This Server has disabled the in-game stats command.\nCheck your stats at MySquadStats.com`
        );
      }

      // The stats shown are those of the match's mod, so without a match
      // there are none to show
      const match = this.match;
      if (!match) {
        await this.server.rcon.warn(
          info.player.steamID,
          `Your stats cannot be shown right now.\nCheck your stats at MySquadStats.com`
        );
        return;
      }

      // Get InGameStats from API
      const dataType = `inGameStats?search=${encodeURIComponent(info.player.steamID)}&dlc=${encodeURIComponent(match.dlc)}&layerClassname=${encodeURIComponent(match.layerClassname)}`;
      const statsResponse = await getDataFromAPI(
        dataType,
        this.options.accessToken
      );

      // Check if the response is valid
      if (
        !statsResponse ||
        !statsResponse.data ||
        statsResponse.data.length === 0
      ) {
        await this.server.rcon.warn(
          info.player.steamID,
          'Error: No stats data received.\nMySquadStats.com may be down.'
        );
        return;
      }

      // Extract the stats from the response
      const stats = statsResponse.data[0];

      await this.server.rcon.warn(
        info.player.steamID,
        `★ Season / All-Time ★\nWounds: ${stats.seasonWounds} / ${stats.totalWounds}\nKills: ${stats.seasonKills} / ${stats.totalKills}\nDeaths: ${stats.seasonDeaths} / ${stats.totalDeaths}\nRevives: ${stats.seasonRevives} / ${stats.totalRevives}\nHighest Killstreak: ${stats.seasonHighestKillstreak} / ${stats.totalHighestKillstreak}\n★ Stats are Delayed - MySquadStats.com ★`
      );
    }
    return;
  }

  async onRoundEnded(info) {
    // The match that ended, before the next game can replace it
    const matchID = this.match?.id ?? null;
    // A game that ended without a match does not get one now
    this.matchPost = null;

    // Ensure winningTeamTracking and its teams are always initialized
    if (!this.winningTeamTracking) {
      this.winningTeamTracking = {};
    }
    if (!this.winningTeamTracking.team1) {
      this.winningTeamTracking.team1 = { consecutiveWins: 0, currentTeam: 1 };
    }
    if (!this.winningTeamTracking.team2) {
      this.winningTeamTracking.team2 = { consecutiveWins: 0, currentTeam: 2 };
    }

    // Patch Request to create Match in API
    const dataType = 'matches';
    let matchData = {};
    const sides = this.roundSides(info);
    if (!sides) {
      // Only one team's result is known, and the other team cannot be told:
      // no result is sent, and the match is closed without one when the
      // next match starts
      this.winningTeamTracking.team1.consecutiveWins = 0;
      this.winningTeamTracking.team2.consecutiveWins = 0;
      matchData = null;
      this.verbose(
        1,
        `RoundEnded-Match | No result | Only the ${info.winner ? 'winner' : 'loser'} of the round is known.`
      );
    } else if (sides.draw) {
      // Reset both teams' winning streaks
      this.winningTeamTracking.team1.consecutiveWins = 0;
      this.winningTeamTracking.team2.consecutiveWins = 0;

      // A draw is sent too, with team IDs 0 and 0
      matchData = {
        match: matchID,
        endTime: info.time,
        winningTeamID: 0,
        winningTeam: 'Draw',
        winningSubfaction: 'Draw',
        winningStreak: 0,
        winningTickets: 0,
        losingTeamID: 0,
        losingTeam: 'Draw',
        losingSubfaction: 'Draw',
        losingTickets: 0,
      };
    } else {
      const { winner, loser } = sides;
      // Update winning streaks
      if (winner.team === this.winningTeamTracking.team1.currentTeam) {
        this.winningTeamTracking.team1.consecutiveWins += 1;
        this.winningTeamTracking.team2.consecutiveWins = 0;
      } else {
        this.winningTeamTracking.team2.consecutiveWins += 1;
        this.winningTeamTracking.team1.consecutiveWins = 0;
      }

      matchData = {
        match: matchID,
        endTime: info.time,
        winningTeamID: winner.team,
        winningTeam: winner.faction,
        winningSubfaction: winner.subfaction,
        winningStreak:
          winner.team === 1
            ? this.winningTeamTracking.team1.consecutiveWins
            : this.winningTeamTracking.team2.consecutiveWins,
        winningTickets: winner.tickets,
        losingTeamID: loser.team,
        losingTeam: loser.faction,
        losingSubfaction: loser.subfaction,
        losingTickets: loser.tickets,
      };
    }

    // Swap team identifiers for the next round
    const temp = this.winningTeamTracking.team1.currentTeam;
    this.winningTeamTracking.team1.currentTeam =
      this.winningTeamTracking.team2.currentTeam;
    this.winningTeamTracking.team2.currentTeam = temp;

    if (!matchData) return;

    // A round end the API answers with an Error, or does not answer, is sent
    // again at the next pings, a few times
    const response = await patchDataInAPI(
      dataType,
      matchData,
      this.options.accessToken,
      { retriesOnError: MATCH_END_RETRIES }
    );
    if (response.status !== 'Success') {
      this.verbose(
        1,
        `RoundEnded-Match | ${response.status} | ${response.message}${response.savedForRetry ? ' | Saved to send again.' : ''}`
      );
    }

    return;
  }

  // The result of a round end: its winner and loser, { draw: true } when it
  // names neither, or null when it cannot be told. SquadJS reads the winner
  // and the loser from separate log lines, so one of them can be missing:
  // the other team is then filled in from the layer (see otherTeam).
  roundSides(info) {
    if (!info.winner && !info.loser) return { draw: true };
    if (info.winner && info.loser) {
      return { winner: info.winner, loser: info.loser };
    }
    const known = info.winner || info.loser;
    const other = this.otherTeam(known);
    if (!other) return null;
    return info.winner
      ? { winner: known, loser: other }
      : { winner: other, loser: known };
  }

  // The team that played against a round end's side: its team ID, and its
  // faction as the layer's teams give it. Its subfaction and tickets are not
  // known, and are sent as null. Null when the faction is not known. With
  // voted factions, the layer's teams are not always the factions played, so
  // the other team is filled in only when the known side played its own
  // team's faction as the layer gives it, and the other team's faction is a
  // different one. The faction filled in is still the layer's: when only the
  // other team voted another one, its team ID, and so every player's win or
  // loss, is right, but its faction name is not. Nothing the plugin reads
  // names that team's faction: the squad list gives its unit's name only.
  otherTeam(side) {
    const team = Number(side.team);
    if (team !== 1 && team !== 2) return null;
    const otherID = 3 - team;
    const layerTeams = this.server.currentLayer?.teams;
    const layerTeam = layerTeams?.[otherID - 1];
    const faction = layerTeam?.faction;
    if (typeof faction !== 'string' || faction.trim() === '') return null;
    if (layerTeams[team - 1]?.faction !== side.faction) return null;
    if (faction === side.faction) return null;
    return {
      // As SquadJS gives it: a string
      team: typeof side.team === 'string' ? String(otherID) : otherID,
      faction,
      // The layer's team name is a setup name, such as RGF_Armored, not a
      // subfaction
      subfaction: null,
      tickets: null,
    };
  }

  async onNewGame(info) {
    // This game, so an older game's match never replaces its match
    const game = ++this.gameCount;
    this.gameStartTime = info.time ?? new Date();
    this.gameLayerClassname = info.layerClassname ?? null;
    this.matchPost = null;
    this.mountMatchUnknown = false;
    // An earlier game's match noted before any game was seen to start: its
    // game ended before this one started
    if (this.earlierMatch && this.earlierMatch.until == null) {
      const until = new Date(this.gameStartTime).getTime();
      this.earlierMatch.until = Number.isNaN(until) ? null : until;
    }

    // Post Request to create Server in API
    let dataType = 'servers';
    const serverData = {
      name: this.server.serverName,
      version: currentVersion,
    };
    const serverResponse = await postDataToAPI(
      dataType,
      serverData,
      this.options.accessToken
    );
    this.verbose(
      1,
      `NewGame-Server | ${serverResponse.status} | ${serverResponse.message}`
    );

    // Post Request to create new Match in API
    dataType = 'matches';
    const newMatchData = {
      server: this.server.serverName,
      dlc: info.dlc,
      mapClassname: info.mapClassname,
      layerClassname: info.layerClassname,
      map: info.layer ? info.layer.map.name : null,
      layer: info.layer ? info.layer.name : null,
      startTime: info.time,
    };
    const matchResponse = await postDataToAPI(
      dataType,
      newMatchData,
      this.options.accessToken
    );
    // A newer game has started meanwhile
    if (game !== this.gameCount) return;
    const match = matchFrom(matchResponse);
    if (match) {
      this.match = match;
      return;
    }
    this.verbose(
      1,
      `NewGame-Post-Match | ${matchResponse.status} | ${matchResponse.message}`
    );

    // The match before is not this game's. Ask for the match instead: it may
    // have been created although its answer was lost. If it was not, the
    // pings ask again, and send the new match again (see recoverMatch).
    this.match = null;
    this.matchPost = {
      game,
      data: newMatchData,
      retryId: matchResponse.retryId ?? null,
    };
    await this.findMatch('NewGame-Get-Match');
    return;
  }

  async onPlayerWounded(info) {
    // Get mssID from connectedPlayers
    let attackerMSSID = null;
    let victimMSSID = null;
    if (info.victim && info.victim.steamID) {
      victimMSSID = await this.getPlayerMSSID(info.victim.steamID);
    }
    if (info.attacker && info.attacker.steamID) {
      attackerMSSID = await this.getPlayerMSSID(info.attacker.steamID);
    }

    // Post Request to create Wound in API
    const dataType = 'wounds';
    const woundData = {
      match: this.match && this.match.id ? this.match.id : null,
      time: info.time,
      victim: info.victim ? info.victim.steamID : null,
      victimMSSID: victimMSSID,
      victimEosID: info.victim ? info.victim.eosID : null,
      victimName: info.victim ? info.victim.name : null,
      victimTeamID: info.victim ? info.victim.teamID : null,
      victimSquadID: info.victim ? info.victim.squadID : null,
      attacker: info.attacker ? info.attacker.steamID : null,
      attackerMSSID: attackerMSSID,
      attackerEosID: info.attacker ? info.attacker.eosID : null,
      attackerName: info.attacker ? info.attacker.name : null,
      attackerTeamID: info.attacker ? info.attacker.teamID : null,
      attackerSquadID: info.attacker ? info.attacker.squadID : null,
      damage: info.damage,
      weapon: info.weapon,
      teamkill: info.teamkill,
    };
    const response = await postDataToAPI(
      dataType,
      woundData,
      this.options.accessToken
    );
    if (response.status === 'Error') {
      this.verbose(
        1,
        `Wounds-Wound | ${response.status} | ${response.message}`
      );
    }
    return;
  }

  async onPlayerDied(info) {
    // Get mssID from connectedPlayers
    let attackerMSSID = null;
    let victimMSSID = null;
    if (info.victim && info.victim.steamID) {
      victimMSSID = await this.getPlayerMSSID(info.victim.steamID);
    }
    if (info.attacker && info.attacker.steamID) {
      attackerMSSID = await this.getPlayerMSSID(info.attacker.steamID);
    }

    if (info.victim) {
      // Post Request to create Death in API
      const dataType = 'deaths';
      const deathData = {
        match: this.match && this.match.id ? this.match.id : null,
        time: info.time,
        woundTime: info.woundTime,
        victim: info.victim ? info.victim.steamID : null,
        victimMSSID: victimMSSID,
        victimEosID: info.victim ? info.victim.eosID : null,
        victimName: info.victim ? info.victim.name : null,
        victimTeamID: info.victim ? info.victim.teamID : null,
        victimSquadID: info.victim ? info.victim.squadID : null,
        attacker: info.attacker ? info.attacker.steamID : null,
        attackerMSSID: attackerMSSID,
        attackerEosID: info.attacker ? info.attacker.eosID : null,
        attackerName: info.attacker ? info.attacker.name : null,
        attackerTeamID: info.attacker ? info.attacker.teamID : null,
        attackerSquadID: info.attacker ? info.attacker.squadID : null,
        damage: info.damage,
        weapon: info.weapon,
        teamkill: info.teamkill,
      };
      const response = await postDataToAPI(
        dataType,
        deathData,
        this.options.accessToken
      );
      if (response.status === 'Error') {
        this.verbose(
          1,
          `Died-Death | ${response.status} | ${response.message}`
        );
      }
    }
    return;
  }

  async onPlayerRevived(info) {
    // Get mssID from connectedPlayers
    let reviverMSSID = null;
    let attackerMSSID = null;
    let victimMSSID = null;
    if (info.reviver && info.reviver.steamID) {
      reviverMSSID = await this.getPlayerMSSID(info.reviver.steamID);
    }
    if (info.attacker && info.attacker.steamID) {
      attackerMSSID = await this.getPlayerMSSID(info.attacker.steamID);
    }
    if (info.victim && info.victim.steamID) {
      victimMSSID = await this.getPlayerMSSID(info.victim.steamID);
    }

    // Post Request to create Revive in API
    const dataType = 'revives';
    const reviveData = {
      match: this.match && this.match.id ? this.match.id : null,
      time: info.time,
      woundTime: info.woundTime,
      victim: info.victim ? info.victim.steamID : null,
      victimMSSID: victimMSSID,
      victimEosID: info.victim ? info.victim.eosID : null,
      victimName: info.victim ? info.victim.name : null,
      victimTeamID: info.victim ? info.victim.teamID : null,
      victimSquadID: info.victim ? info.victim.squadID : null,
      attacker: info.attacker ? info.attacker.steamID : null,
      attackerMSSID: attackerMSSID,
      attackerEosID: info.attacker ? info.attacker.eosID : null,
      attackerName: info.attacker ? info.attacker.name : null,
      attackerTeamID: info.attacker ? info.attacker.teamID : null,
      attackerSquadID: info.attacker ? info.attacker.squadID : null,
      damage: info.damage,
      weapon: info.weapon,
      teamkill: info.teamkill,
      reviver: info.reviver ? info.reviver.steamID : null,
      reviverMSSID: reviverMSSID,
      reviverEosID: info.reviver ? info.reviver.eosID : null,
      reviverName: info.reviver ? info.reviver.name : null,
      reviverTeamID: info.reviver ? info.reviver.teamID : null,
      reviverSquadID: info.reviver ? info.reviver.squadID : null,
    };
    const response = await postDataToAPI(
      dataType,
      reviveData,
      this.options.accessToken
    );
    if (response.status === 'Error') {
      this.verbose(
        1,
        `Revives-Revive | ${response.status} | ${response.message}`
      );
    }
    return;
  }

  async onPlayerConnected(info) {
    if (!info.player || !info.player.steamID) {
      return this.verbose(1, 'ERROR: Connected-Player | No SteamID');
    }
    let playerData = {};
    if (
      this.server.a2sPlayerCount <= 50 &&
      this.server.currentLayer &&
      this.server.currentLayer.gamemode === 'Seed'
    ) {
      playerData = {
        isSeeder: 1,
      };
    }

    // Patch Request to create Player in API
    const dataType = 'players';
    playerData = {
      ...playerData,
      eosID: info.player.eosID,
      steamID: info.player.steamID,
      lastName: info.player.name,
      lastIP: info.ip,
    };
    const response = await patchDataInAPI(
      dataType,
      playerData,
      this.options.accessToken
    );
    if (response.status === 'Error') {
      this.verbose(
        1,
        `Connected-Player | ${response.status} | ${response.message}`
      );
    } else if (response.status === 'Success') {
      // Add to connected Players
      this.connectedPlayers[info.player.steamID] = {
        mssID: response.data.mssID,
      };
    }
    return;
  }

  // KILLSTREAKS
  async killstreakWounded(info) {
    if (!info.attacker) return;
    if (info.teamkill === true) return;

    // Get the attacker's Steam ID
    const steamID = info.attacker.steamID;

    // Check if this is the first time the attacker has made a killstreak
    if (!this.trackedKillstreaks.hasOwnProperty(steamID)) {
      // Set the player's initial killstreak to 0
      this.trackedKillstreaks[steamID] = 0;
    }

    // Increment the player's kill streak by 1
    this.trackedKillstreaks[steamID] += 1;
  }

  async killstreakDied(info) {
    if (!info.victim) return;
    // GC Driod Support
    // Geonosian Hive
    const gcDroidFactions = [
      'Droid Army',
      'Droid Army - Lego',
      'Droid Army - SpecOps',
      'Droid Army - Camo',
      'Droid Army - Snow',
      'Droid Army - Mech',
      'Droid Army - Halloween',
      'Droid Army - Geonosis',
    ];
    // If info.victim.squad.teamName is in gcDroidFactions
    if (gcDroidFactions.includes(info?.victim?.squad?.teamName)) {
      this.verbose(2, `Droid Army Detected: ${info.victim.squad.teamName}`);
      // Call the onWound function with the info object
      this.killstreakWounded(info);
    }
    const steamID = info.victim.steamID;
    // The streak ends here: taken now, so a kill made while it is sent
    // starts the next one
    const killstreak = this.trackedKillstreaks[steamID];
    delete this.trackedKillstreaks[steamID];

    // Update highestKillstreak in the SQL database
    const { matchID, time } = this.killstreakTarget(info.time);
    await this.updateHighestKillstreak(steamID, killstreak, matchID, time);
  }

  async killstreakRoundEnded(info) {
    // The streaks held now were made in the match that ended. They are sent
    // with its ID and its round end, whenever they end (see killstreakTarget)
    this.killstreakEndedMatch = {
      matchID: this.match?.id ?? null,
      time: info?.time ?? new Date(),
    };
  }

  // The match a streak that ends now was made in, and when it ended: after a
  // round end, the match that ended and its round end, as the API takes a
  // streak of a closed match only up to a minute after its round end;
  // otherwise the match being played and the time given.
  killstreakTarget(time) {
    if (this.killstreakEndedMatch) {
      return { ...this.killstreakEndedMatch };
    }
    return { matchID: this.match?.id ?? null, time: time ?? new Date() };
  }

  async killstreakNewGame(info) {
    // The streaks held now were made in the match that ended: at its round
    // end, or now when there was none (a layer change). Taken before the new
    // game's match replaces this.match.
    const { matchID, time } = this.killstreakTarget(info?.time);
    this.killstreakEndedMatch = null;
    const killstreaks = this.trackedKillstreaks;
    this.trackedKillstreaks = {};

    // Loop through them
    for (const [steamID, killstreak] of Object.entries(killstreaks)) {
      // Update highestKillstreak in the SQL database
      await this.updateHighestKillstreak(steamID, killstreak, matchID, time);
    }
    return;
  }

  async killstreakDisconnected(info) {
    if (!info?.player?.steamID) {
      return;
    }
    const steamID = info.player.steamID;
    const killstreak = this.trackedKillstreaks[steamID];
    delete this.trackedKillstreaks[steamID];

    // Update highestKillstreak in the SQL database
    const { matchID, time } = this.killstreakTarget(info.time);
    await this.updateHighestKillstreak(steamID, killstreak, matchID, time);

    // Remove from connectedPlayers
    if (this.connectedPlayers.hasOwnProperty(info.player.steamID)) {
      delete this.connectedPlayers[info.player.steamID];
    }
  }

  // Sends a player's streak, made in the match given and ended at the time
  // given. Nothing is sent without a streak or without a match.
  async updateHighestKillstreak(steamID, currentKillstreak, matchID, time) {
    // Return is the player's current killstreak is 0
    if (!currentKillstreak || currentKillstreak === 0) return;
    // The API needs a player and a match
    if (!steamID || steamID === 'undefined') return;
    if (!matchID) {
      this.verbose(
        2,
        `Killstreak of ${currentKillstreak} for ${steamID} not sent: no match.`
      );
      return;
    }

    // Get mssID from connectedPlayers
    const mssID = await this.getPlayerMSSID(steamID);
    try {
      // Patch Request to update highestKillstreak in API
      const dataType = 'playerKillstreaks';
      const playerData = {
        steamID: steamID,
        mssID: mssID,
        highestKillstreak: currentKillstreak,
        match: matchID,
        time: time,
      };
      const response = await patchDataInAPI(
        dataType,
        playerData,
        this.options.accessToken
      );
      if (response.status === 'Error') {
        this.verbose(
          1,
          `Error updating highestKillstreak in database for ${steamID}: ${response.message}`
        );
      }
    } catch (error) {
      this.verbose(
        1,
        `Error updating highestKillstreak in database for ${steamID}: ${error}`
      );
    }
    return;
  }

  async getPlayerMSSID(steamID) {
    if (this.connectedPlayers.hasOwnProperty(steamID)) {
      return this.connectedPlayers[steamID].mssID;
    } else {
      return null;
    }
  }
}

// Retrieve the latest version of code from GitHub
async function getLatestVersion(owner, repo) {
  const url = `https://api.github.com/repos/${owner}/${repo}/releases/latest`;
  const options =
    typeof AbortSignal !== 'undefined' &&
    typeof AbortSignal.timeout === 'function'
      ? { signal: AbortSignal.timeout(DOWNLOAD_TIMEOUT) }
      : {};
  const response = await fetch(url, options);
  const data = await response.json();
  return data.tag_name;
}

async function compareVersions(version1, version2) {
  const v1Parts = version1.replace('v', '').split('.').map(Number);
  const v2Parts = version2.replace('v', '').split('.').map(Number);

  for (let i = 0; i < Math.max(v1Parts.length, v2Parts.length); i++) {
    const v1 = v1Parts[i] || 0;
    const v2 = v2Parts[i] || 0;

    if (v1 > v2) return 1;
    if (v1 < v2) return -1;
  }

  return 0;
}

// The match in an answer from /matches, or null. GET /matches answers with an
// empty body when the server has no open match, and an Error has no match.
function matchFrom(response) {
  const match =
    response && typeof response === 'object' ? response.match : null;
  return match && typeof match === 'object' && match.id ? match : null;
}

// Whether a match can be the match of the game that started at gameStartTime
// on the layer gameLayerClassname: it is on that layer, and it started at
// most MATCH_START_SLACK before or after the game. What is not known is not
// checked: when the plugin started during a game, only the layer SquadJS
// gave at mount is (see mount and pingMySquadStats), and that the match
// started at most OPEN_MATCH_MAX_AGE ago.
function isMatchOfGame(match, gameStartTime, gameLayerClassname) {
  if (
    gameLayerClassname &&
    match.layerClassname &&
    match.layerClassname !== gameLayerClassname
  ) {
    return false;
  }
  if (match.startTime == null) return true;
  const matchStart = new Date(match.startTime).getTime();
  if (Number.isNaN(matchStart)) return true;
  if (!gameStartTime) return Date.now() - matchStart <= OPEN_MATCH_MAX_AGE;
  const gameStart = new Date(gameStartTime).getTime();
  if (Number.isNaN(gameStart)) return true;
  return Math.abs(matchStart - gameStart) <= MATCH_START_SLACK;
}

function handleApiError(error) {
  if (error.response) {
    let errMsg = `${error.response.status} - ${error.response.statusText}`;
    const status = 'Error';
    if (error.response.status === 502) {
      errMsg += ' Unable to connect to the API. MySquadStats is likely down.';
    } else if (error.response.status === 500) {
      errMsg += ' Internal server error. Something went wrong on the server.';
    }
    return {
      status: status,
      message: errMsg,
      httpStatus: error.response.status,
    };
  } else if (error.request) {
    // The request was made but no response was received, or not in time
    return {
      status: 'Error',
      message:
        // Added Status Page
        //  'No response received from the API. Please check network connections or https://status.mysquadstats.com/.',
        `No response received from the API (${error.message}). Please check network connections or reach out in the Squad Stats Discord if this lasts more than 15 minutes.`,
      noAnswer: true,
    };
  } else {
    // Something happened in setting up the request that triggered an Error
    return {
      status: 'Error',
      message: `Error: ${error.message}`,
    };
  }
}

// Requests that got a 502 (MySquadStats was down), and round ends that the
// API answered with an Error, are saved in files, by method, and sent again
// after a ping is answered. Several servers can run from one SquadJS install,
// one process each, and then share MySquadStats_Data, so each server has its
// own files, named after a short one-way hash of its access token (never the
// token itself): no two processes ever write the same file. Earlier versions
// saved every server's requests to the files without a hash (see
// claimLegacyRetryFiles).
const RETRY_FILES = {
  post: 'send-retry-requests',
  patch: 'patch-retry-requests',
};
// Orders the requests saved in the same millisecond
let retrySeq = 0;

function dataDirPath() {
  return path.join(
    fileURLToPath(import.meta.url),
    '..',
    '..',
    'MySquadStats_Data'
  );
}

function tokenHash(accessToken) {
  return crypto
    .createHash('sha256')
    .update(String(accessToken))
    .digest('hex')
    .slice(0, 12);
}

// This server's retry file for the method given
function retryFilePath(method, accessToken) {
  return path.join(
    dataDirPath(),
    `${RETRY_FILES[method]}-${tokenHash(accessToken)}.json`
  );
}

// The requests saved in a retry file. A file whose text is not a list, as
// when it was changed by hand, counts as empty, and is replaced at the next
// change. A file that cannot be read now, as when too many files are open or
// another program holds it, counts as empty too, except with strict: it then
// throws, so that it is never replaced from an empty list (see
// changeRetryFile).
function readRetryFile(filePath, strict = false) {
  let text;
  try {
    text = fs.readFileSync(filePath, 'utf8');
  } catch (error) {
    if (error.code === 'ENOENT') return [];
    if (strict) throw error;
    console.log(`MySquadStats | Could not read ${filePath}: ${error.message}`);
    return [];
  }
  try {
    const requests = JSON.parse(text);
    if (Array.isArray(requests)) {
      return requests.filter(
        (request) => request && typeof request === 'object'
      );
    }
  } catch (error) {
    console.log(`MySquadStats | Could not read ${filePath}: ${error.message}`);
  }
  return [];
}

// Writes a retry file whole: to a temporary file first, which is then moved
// over it, so the file is never left half-written, as when SquadJS stops
// mid-write.
function writeRetryFile(filePath, text) {
  const tempPath = `${filePath}.${process.pid}.tmp`;
  fs.writeFileSync(tempPath, text);
  try {
    fs.renameSync(tempPath, filePath);
  } catch (error) {
    // Windows can refuse to replace a file another program has open, such
    // as a virus scanner: it is then written in place
    fs.rmSync(tempPath, { force: true });
    fs.writeFileSync(filePath, text);
  }
}

// Changes the requests saved in a retry file as the file is now, so requests
// saved meanwhile are kept. Deletes the file when none is left. A change that
// returns the requests it was given leaves the file as it is. Throws when the
// file cannot be read now, and leaves it as it is (every caller catches it).
function changeRetryFile(filePath, change) {
  const saved = readRetryFile(filePath, true);
  const requests = change(saved);
  if (requests === saved) return;
  if (requests.length > 0) {
    fs.mkdirSync(path.dirname(filePath), { recursive: true });
    writeRetryFile(filePath, JSON.stringify(requests));
  } else if (fs.existsSync(filePath)) {
    fs.unlinkSync(filePath);
  }
}

// Saves a request to send again. retriesOnError: how many times it is sent
// again after the API answers it with an Error (a 502 never counts). Returns
// its ID.
function saveRetryRequest(method, dataType, data, retriesOnError, accessToken) {
  const request = {
    id: crypto.randomUUID(),
    savedAt: Date.now(),
    seq: ++retrySeq,
    dataType: `${dataType}`,
    data: data,
  };
  if (retriesOnError > 0) request.retriesOnError = retriesOnError;
  changeRetryFile(retryFilePath(method, accessToken), (requests) => [
    ...requests,
    request,
  ]);
  return request.id;
}

// The codes of read errors that pass: too many files open, or the file held
// for a moment by another program, such as a virus scanner
const PASSING_READ_ERRORS = ['EMFILE', 'ENFILE', 'EBUSY', 'EAGAIN'];

// Whether a request saved in a retry file passes the test, or null when the
// file cannot be read now but can soon (see PASSING_READ_ERRORS), so that the
// checks below never take a request as gone while it may still be saved. A
// file that cannot be read for another reason, as when its owner or mode is
// wrong, counts as empty, as it does for the requests sent again (see
// readRetryFile).
function someSaved(filePath, test) {
  let requests;
  try {
    requests = readRetryFile(filePath, true);
  } catch (error) {
    console.log(`MySquadStats | Could not read ${filePath}: ${error.message}`);
    return PASSING_READ_ERRORS.includes(error.code) ? null : false;
  }
  return requests.some(test);
}

// Whether the request with this ID is still saved to send again. One whose
// file cannot be read now counts as saved (see someSaved).
function isSavedForRetry(method, id, accessToken) {
  return (
    someSaved(
      retryFilePath(method, accessToken),
      (request) => request.id === id
    ) !== false
  );
}

// A request saved by an earlier version, as this version saves it: the
// player lists they saved are snapshots that newer lists have replaced, so
// they are dropped (null), and a request without an ID gets one to remove it
// by, and goes first. index is its place in its file: the ID comes from it
// and the request, so the same request taken twice gets the same ID.
function takeLegacyRequest(request, index) {
  if (request.dataType === 'serversPlayers') return null;
  if (request.id) return request;
  const id = crypto
    .createHash('sha256')
    .update(`${index}\n${JSON.stringify(request)}`)
    .digest('hex')
    .slice(0, 32);
  return { ...request, id: `legacy-${id}`, savedAt: 0, seq: 0 };
}

// Earlier versions saved every server's requests to the files without a hash.
// At mount, a server takes what they hold into its own files: each file is
// first moved to a name of this server's in one step, so that only one
// server takes it and no other process is writing it, and is then added to
// this server's file and deleted. A file taken at an earlier start that
// stopped before it was added is added now. Whatever cannot be done now is
// left for the next start, and a request is never added twice. Returns how
// many requests were taken and how many player lists dropped.
function claimLegacyRetryFiles(accessToken, log) {
  const hash = tokenHash(accessToken);
  const result = { taken: 0, droppedLists: 0 };
  for (const method of Object.keys(RETRY_FILES)) {
    const legacyPath = path.join(dataDirPath(), `${RETRY_FILES[method]}.json`);
    const claimPath = path.join(
      dataDirPath(),
      `${RETRY_FILES[method]}-${hash}.claimed.json`
    );
    const ownPath = retryFilePath(method, accessToken);
    // Throws when the file is left for the next start, so that the file
    // without a hash is not moved over it
    const addClaimed = () => {
      let requests;
      let unreadable = null;
      try {
        requests = JSON.parse(fs.readFileSync(claimPath, 'utf8'));
      } catch (error) {
        // A file that cannot be opened now, as when another program holds
        // it, is left as it is
        if (error.code) throw error;
        unreadable = error.message;
      }
      if (!unreadable && !Array.isArray(requests)) unreadable = 'not a list';
      if (unreadable) {
        // Kept for a look by hand, and not taken again
        const keptPath = path.join(
          dataDirPath(),
          `${RETRY_FILES[method]}-${hash}.unreadable-${Date.now()}.json`
        );
        fs.renameSync(claimPath, keptPath);
        log(
          `Could not read the requests saved by an earlier version (${unreadable}). The file is kept as ${keptPath}.`
        );
        return;
      }
      const taken = [];
      let droppedLists = 0;
      requests.forEach((request, index) => {
        if (!request || typeof request !== 'object') return;
        const kept = takeLegacyRequest(request, index);
        if (kept) taken.push(kept);
        else droppedLists++;
      });
      // A request taken at an earlier start is not added again
      let added = [];
      changeRetryFile(ownPath, (saved) => {
        const savedIds = new Set(saved.map((request) => request.id));
        added = taken.filter((request) => !savedIds.has(request.id));
        return added.length > 0 ? [...saved, ...added] : saved;
      });
      try {
        fs.unlinkSync(claimPath);
      } catch (error) {
        // Windows can refuse to delete a file another program has open, such
        // as a virus scanner. It is emptied instead, so that a later start
        // does not add its requests again once they are sent. Failing that,
        // they are taken out of this server's file again, and taken at the
        // next start.
        try {
          fs.writeFileSync(claimPath, '[]');
        } catch (writeError) {
          const addedIds = new Set(added.map((request) => request.id));
          changeRetryFile(ownPath, (saved) => {
            const kept = saved.filter((request) => !addedIds.has(request.id));
            return kept.length === saved.length ? saved : kept;
          });
          throw error;
        }
      }
      result.taken += added.length;
      result.droppedLists += droppedLists;
    };
    try {
      if (fs.existsSync(claimPath)) addClaimed();
      try {
        fs.renameSync(legacyPath, claimPath);
      } catch (error) {
        // None saved, or another server took them first
        if (error.code === 'ENOENT') continue;
        throw error;
      }
      addClaimed();
    } catch (error) {
      log(
        `Could not take the requests saved by an earlier version in ${legacyPath}: ${error.message}. They are left to take at the next start.`
      );
    }
  }
  return result;
}

// The names of the files in MySquadStats_Data of other access tokens that
// match the pattern, whose one group is the token's code
function otherTokenFiles(accessToken, pattern) {
  const hash = tokenHash(accessToken);
  let names;
  try {
    names = fs.readdirSync(dataDirPath());
  } catch (error) {
    return [];
  }
  return names.filter((name) => {
    const found = pattern.exec(name);
    return found && found[1] !== hash;
  });
}

// The retry files of other access tokens: another server's, or this
// server's from before its access token was changed
function otherRetryFiles(accessToken) {
  return otherTokenFiles(
    accessToken,
    /^(?:send|patch)-retry-requests-([0-9a-f]{12})\.json$/
  );
}

// Prepares this server's saved requests to be sent: a request without an ID,
// as one put in its file by hand, gets one (see takeLegacyRequest). Returns
// how many player lists were dropped.
function prepareSavedRequests(accessToken) {
  let droppedLists = 0;
  for (const method of Object.keys(RETRY_FILES)) {
    const filePath = retryFilePath(method, accessToken);
    const needsChange = (request) =>
      !request.id || request.dataType === 'serversPlayers';
    if (!readRetryFile(filePath).some(needsChange)) continue;
    changeRetryFile(filePath, (saved) => {
      const kept = [];
      saved.forEach((request, index) => {
        const taken = takeLegacyRequest(request, index);
        if (taken) kept.push(taken);
        else droppedLists++;
      });
      return kept;
    });
  }
  return droppedLists;
}

// Whether a request saved in the patch file is a round end that closes this
// match: one that names it, or one without a match ID (saved by earlier
// versions, or when the plugin had no match) that ended after the match
// started, as the API then closes the newest match that started before the
// round end.
function closesMatch(request, match) {
  if (request.dataType !== 'matches') return false;
  const data =
    request.data && typeof request.data === 'object' ? request.data : {};
  if (data.match != null) return Number(data.match) === Number(match.id);
  const start = new Date(match.startTime).getTime();
  const end = new Date(data.endTime).getTime();
  return !Number.isNaN(start) && !Number.isNaN(end) && end >= start;
}

// Whether a round end saved to send again closes this match (see
// closesMatch), or null when the file cannot be read now (see someSaved)
function isRoundEndSaved(match, accessToken) {
  return someSaved(retryFilePath('patch', accessToken), (request) =>
    closesMatch(request, match)
  );
}

// Removes the new match saved to send again for the game whose match was
// found: the one with the ID given, and any saved with the match's layer and
// start, as sending it now would create the game's match a second time.
function removeSavedNewMatch(match, retryId, accessToken) {
  const start = new Date(match.startTime).getTime();
  const isOfMatch = (request) => {
    if (retryId && request.id === retryId) return true;
    const data =
      request.data && typeof request.data === 'object' ? request.data : {};
    const sentStart = new Date(data.startTime).getTime();
    return (
      Boolean(match.layerClassname) &&
      data.layerClassname === match.layerClassname &&
      !Number.isNaN(start) &&
      !Number.isNaN(sentStart) &&
      Math.abs(sentStart - start) <= MATCH_START_SLACK
    );
  };
  changeRetryFile(retryFilePath('post', accessToken), (saved) => {
    const kept = saved.filter(
      (request) => !(request.dataType === 'matches' && isOfMatch(request))
    );
    return kept.length === saved.length ? saved : kept;
  });
}

// The time an earlier game's match left open (see the plugin's
// noteEarlierMatch) covers: from its start, less MATCH_START_SLACK, until its
// game ended, at the earliest saved round end that closes it (see
// closesMatch), or else when the game after it started. Null when neither
// end is known, or when that end is more than OPEN_MATCH_MAX_AGE after the
// match started: the match was then left open long before that game.
function earlierMatchWindow(earlier, requests) {
  if (!earlier) return null;
  const start = new Date(earlier.startTime).getTime();
  if (Number.isNaN(start)) return null;
  let until = earlier.until == null ? Infinity : earlier.until;
  for (const request of requests) {
    if (request.method !== 'patch' || !closesMatch(request, earlier)) continue;
    const end = new Date(request.data?.endTime).getTime();
    if (end < until) until = end;
  }
  if (until === Infinity || until - start > OPEN_MATCH_MAX_AGE) return null;
  return { id: earlier.id, since: start - MATCH_START_SLACK, until };
}

// The data to send a saved request with. A wound, death or revive saved with
// no match, as when the plugin had none during an outage, is sent with its
// game's match when that is known by now, as the API ties an event without a
// match only to a closed match, and these matches are still open:
// - gameMatch: the match of the game being played, for an event at or after
//   gameMatch.since (see the plugin's gameMatch);
// - replayedMatch: the match created by the last new match sent again in
//   this pass, for an event at or after its start, less MATCH_START_SLACK;
// - earlier: an earlier game's match left open, for an event in the time it
//   covers (see earlierMatchWindow). Its round end then counts the event,
//   whether or not a newer match has closed it by then.
// The saved request itself is not changed.
function dataToSend(request, replayedMatch, gameMatch, earlier) {
  const data = request.data;
  if (
    !EVENT_DATA_TYPES.includes(request.dataType) ||
    !data ||
    typeof data !== 'object' ||
    data.match != null
  ) {
    return data;
  }
  const time = new Date(data.time).getTime();
  if (Number.isNaN(time)) return data;
  if (gameMatch && time >= new Date(gameMatch.since).getTime()) {
    return { ...data, match: gameMatch.id };
  }
  if (
    replayedMatch &&
    time >= new Date(replayedMatch.startTime).getTime() - MATCH_START_SLACK
  ) {
    return { ...data, match: replayedMatch.id };
  }
  if (earlier && time >= earlier.since && time <= earlier.until) {
    return { ...data, match: earlier.id };
  }
  return data;
}

// The IDs of this server's saved requests that were sent again and answered,
// one a line, added as each answer comes, until they are removed from the
// retry files: a stop between two removals then sends again only the request
// that was being sent (see removeAnsweredRequests). One file per access
// token, like the retry files.
function answeredFilePath(accessToken) {
  return path.join(dataDirPath(), `retry-done-${tokenHash(accessToken)}.log`);
}

function noteAnsweredRequest(id, accessToken) {
  try {
    fs.appendFileSync(answeredFilePath(accessToken), `${id}\n`);
  } catch (error) {
    // Then only a stop before the next removal sends it again
  }
}

// Deletes the list of answered requests once they are removed from the
// retry files. One that cannot be deleted names only requests no longer
// saved, so it is left as it is.
function forgetAnsweredRequests(accessToken) {
  try {
    fs.rmSync(answeredFilePath(accessToken), { force: true });
  } catch (error) {
    // Left as it is
  }
}

// Removes from this server's retry files the requests answered before
// SquadJS stopped, before they were removed (see answeredFilePath). The
// lists of other access tokens are read too: when a server's access token
// was changed after such a stop, its requests are taken by the new token
// (see the README) and are listed under the old one. Request IDs are random,
// so another server's never match. Only this server's list is deleted, and
// another token's list that cannot be read now is skipped. Throws when this
// server's list or a retry file cannot be read now, so that the requests are
// not sent again; they are then removed at the next ping.
function removeAnsweredRequests(accessToken) {
  const ids = new Set();
  const addIds = (text) => {
    for (const id of text.split('\n')) if (id) ids.add(id);
  };
  let listed = true;
  try {
    addIds(fs.readFileSync(answeredFilePath(accessToken), 'utf8'));
  } catch (error) {
    if (error.code !== 'ENOENT') throw error;
    listed = false;
  }
  const others = otherTokenFiles(
    accessToken,
    /^retry-done-([0-9a-f]{12})\.log$/
  );
  for (const name of others) {
    try {
      addIds(fs.readFileSync(path.join(dataDirPath(), name), 'utf8'));
    } catch (error) {
      // Skipped
    }
  }
  if (ids.size > 0) {
    for (const method of Object.keys(RETRY_FILES)) {
      changeRetryFile(retryFilePath(method, accessToken), (saved) => {
        const kept = saved.filter((request) => !ids.has(String(request.id)));
        return kept.length === saved.length ? saved : kept;
      });
    }
  }
  if (listed) forgetAnsweredRequests(accessToken);
}

// Whether a round end sent again ends the match created by a new match sent
// again before it: unless it ended before that match started (less
// MATCH_START_SLACK), as an earlier version's round end of the game before
// can when the times saved do not tell their order (see legacyInSendOrder).
// A round end whose end is not known ends it.
function endsMatch(data, match) {
  if (!match) return false;
  const endTime = data && typeof data === 'object' ? data.endTime : null;
  const end = endTime == null ? NaN : new Date(endTime).getTime();
  const start = new Date(match.startTime).getTime();
  return (
    Number.isNaN(end) || Number.isNaN(start) || end >= start - MATCH_START_SLACK
  );
}

// The requests an earlier version saved (see takeLegacyRequest) in the order
// they happened. It saved new matches, wounds, deaths and revives in one file
// and round ends in the other, with no time of saving: by file alone, a round
// end would go after the next game's new match. Each file's requests are put
// in the order they happened, as the earlier version's own replay could write
// them back with its new matches first, and the two files are then merged in
// that order: by an event's time, a round end's end or a new match's start.
// A request without one, such as a player's, takes the time of the request
// before it in its file.
function legacyInSendOrder(requests) {
  const timed = (method) => {
    let last = -Infinity;
    return requests
      .filter((request) => request.method === method)
      .map((request) => {
        const data =
          request.data && typeof request.data === 'object' ? request.data : {};
        const value = data.time ?? data.endTime ?? data.startTime;
        const time = value == null ? NaN : new Date(value).getTime();
        if (!Number.isNaN(time)) last = time;
        return { request, time: last };
      })
      .sort((a, b) => a.time - b.time || 0);
  };
  const posts = timed('post');
  const patches = timed('patch');
  const order = [];
  let i = 0;
  let j = 0;
  while (i < posts.length || j < patches.length) {
    const takePost =
      j >= patches.length ||
      (i < posts.length && posts[i].time <= patches[j].time);
    order.push(takePost ? posts[i++].request : patches[j++].request);
  }
  return order;
}

// The saved requests in the order they are sent again: the order they were
// first sent in, across both files, except that a wound, death or revive
// saved after a round end, with no new match or round end between them,
// goes before it when it happened before the round ended, as when its answer
// came after the round end's: the round end then counts it. The requests an
// earlier version saved go first, in the order they happened (see
// legacyInSendOrder).
function inSendOrder(requests) {
  const sorted = [
    ...legacyInSendOrder(requests.filter((request) => !request.savedAt)),
    ...requests
      .filter((request) => request.savedAt)
      .sort((a, b) => a.savedAt - b.savedAt || (a.seq || 0) - (b.seq || 0)),
  ];
  const order = [];
  // The place of the last round end, while no new match or round end has
  // come after it, and when it ended
  let roundEnd = null;
  for (const request of sorted) {
    if (request.dataType === 'matches') {
      order.push(request);
      const end = new Date(request.data?.endTime).getTime();
      roundEnd =
        request.method === 'patch' && !Number.isNaN(end)
          ? { at: order.length - 1, end }
          : null;
    } else if (
      roundEnd &&
      EVENT_DATA_TYPES.includes(request.dataType) &&
      new Date(request.data?.time).getTime() <= roundEnd.end
    ) {
      order.splice(roundEnd.at, 0, request);
      roundEnd.at++;
    } else {
      order.push(request);
    }
  }
  return order;
}

// Sends this server's saved requests again (see prepareSavedRequests), in
// the order they were first sent across its two files (see inSendOrder), so
// a round end goes before what came after it. A request the API answers is
// removed, except a round end answered with an Error, which is kept for a few
// more tries. A request that gets a 502 again is kept, and it and the
// requests after it wait for the next ping, unless it has had
// RETRY_502_LIMIT of them; so does a new match that gets no answer, and so
// do the requests after any other request that got no answer, other than a
// round end (see below). Wounds, deaths and revives saved with no match are
// sent with their match when it is known (see dataToSend): getGameMatch()
// gives the match of the game being played, and earlierMatch an earlier
// game's match left open (see the plugin's noteEarlierMatch). One that is
// still to go out with no match while a round end or new match is saved
// after it is sent once after the last of these instead, as the API ties an
// event with no match only to a closed match, and its match can be open
// until then; a pass cut short leaves it in its place. A round end that
// names no match, right after such events, goes after them too when a new
// match is saved after it, or when the game being played started after it
// ended, so that its match's totals and result count them. A moved event
// that would still go out with no match waits for the next ping, with what
// was moved after it, when a new match was answered in this pass, and so
// does one the API finds no match for, as its match can still be open,
// until one of them is dropped after RETRY_502_LIMIT such answers.
// onAnswer(request, answer) is called with each answer. Returns what was
// done, or null when nothing was saved.
async function retryFailedRequests(
  accessToken,
  log,
  onAnswer,
  getGameMatch,
  earlierMatch
) {
  removeAnsweredRequests(accessToken);
  const droppedLists = prepareSavedRequests(accessToken);
  const listsNote = droppedLists
    ? ` ${droppedLists} saved player list${droppedLists === 1 ? '' : 's'} dropped.`
    : '';

  const saved = [];
  for (const method of Object.keys(RETRY_FILES)) {
    for (const request of readRetryFile(retryFilePath(method, accessToken))) {
      saved.push({ ...request, method });
    }
  }
  if (saved.length === 0) {
    return listsNote ? `Finished retrying failed requests:${listsNote}` : null;
  }
  const failedRequests = inSendOrder(saved);
  const earlier = earlierMatchWindow(earlierMatch, failedRequests);

  // Send Ping to MySquadStats with amount of failed requests
  const pingDataType = 'ping';
  const pingData = {
    filePath: dataDirPath(),
    failedRequests: failedRequests.length,
  };
  const pingResponse = await postDataToAPI(
    pingDataType,
    pingData,
    accessToken,
    {
      saveForRetry: false,
    }
  );
  log(`Ping-MySquadStats | ${pingResponse.status} | ${pingResponse.message}`);

  // The requests sent or dropped are removed from the files in batches, as
  // the files are then, so requests saved meanwhile are kept
  const done = {};
  for (const method of Object.keys(RETRY_FILES)) done[method] = new Set();
  let doneCount = 0;
  let removedAt = Date.now();
  const removeDone = () => {
    for (const [method, ids] of Object.entries(done)) {
      if (ids.size === 0) continue;
      changeRetryFile(retryFilePath(method, accessToken), (saved) =>
        saved.filter((item) => !ids.has(item.id))
      );
      ids.clear();
    }
    // Every request it names is now removed
    forgetAnsweredRequests(accessToken);
    doneCount = 0;
    removedAt = Date.now();
  };
  const changeSaved = (request, change) => {
    changeRetryFile(retryFilePath(request.method, accessToken), (saved) =>
      saved.map((item) => (item.id === request.id ? change(item) : item))
    );
  };

  // The match created by the last new match sent again, until a round end
  // that ends it is sent again (see endsMatch)
  let replayedMatch = null;
  // The requests in the order they are sent: an event or round end moved
  // after the last round end or new match is added again at the end
  const queue = [...failedRequests];
  let lastMatchIndex = -1;
  let lastNewMatchIndex = -1;
  failedRequests.forEach((request, index) => {
    if (request.dataType !== 'matches') return;
    lastMatchIndex = index;
    if (request.method === 'post') lastNewMatchIndex = index;
  });
  // Whether an event was moved (see below) since the last round end or new
  // match the pass came to
  let movedEvents = false;
  // Whether a new match sent again in this pass was answered with its match
  let newMatchAnswered = false;
  // Whether a moved event was dropped in this pass after RETRY_502_LIMIT
  // answers that no match was found for it (see below)
  let movedGivenUp = false;
  let sent = 0;
  let dropped = 0;
  let skipped = 0;
  try {
    for (let index = 0; index < queue.length; index++) {
      const request = queue[index];
      const isMatchRequest = request.dataType === 'matches';
      // A new match or round end can take a while to be answered (a round
      // end waits for the server's player list in the API), so the requests
      // answered before it are removed first
      if (
        doneCount >= RETRY_REMOVE_BATCH ||
        (doneCount > 0 &&
          (isMatchRequest || Date.now() - removedAt >= RETRY_REMOVE_INTERVAL))
      ) {
        removeDone();
      }
      const remove = () => {
        done[request.method].add(request.id);
        doneCount++;
        noteAnsweredRequest(request.id, accessToken);
        // A new match or round end is removed at once, so that it is not
        // sent again at the next start
        if (isMatchRequest) removeDone();
      };
      // A new match removed meanwhile, as its game's match was found (see
      // takeMatch), is not sent. One whose file cannot be read now is sent
      // (see isSavedForRetry): the API then gives the match it created
      // before.
      if (
        isMatchRequest &&
        request.method === 'post' &&
        !isSavedForRetry('post', request.id, accessToken)
      ) {
        skipped++;
        continue;
      }

      const gameMatch = getGameMatch ? getGameMatch() : null;
      const data = dataToSend(request, replayedMatch, gameMatch, earlier);
      const noMatch =
        EVENT_DATA_TYPES.includes(request.dataType) &&
        data &&
        typeof data === 'object' &&
        data.match == null;
      // An event moved (see below) that would still go out with no match
      // waits for the next ping, with what was moved after it, when a new
      // match was answered in this pass: the API closes the matches left
      // open before that match only after answering it, so its match can
      // still be open
      if (index >= failedRequests.length && newMatchAnswered && noMatch) {
        break;
      }
      // A wound, death or revive that would go out with no match, as when
      // SquadJS restarted during its game while MySquadStats was down, is
      // sent once the round end or new match saved after it has closed its
      // match. A request is moved only from its first place, so at most once.
      if (index < lastMatchIndex && noMatch) {
        queue.push(request);
        movedEvents = true;
        continue;
      }
      if (isMatchRequest) {
        const roundEndAfterMoved =
          movedEvents &&
          request.method === 'patch' &&
          index < failedRequests.length &&
          (!data || typeof data !== 'object' || data.match == null) &&
          (index < lastNewMatchIndex ||
            (gameMatch !== null &&
              new Date(data?.endTime).getTime() <
                new Date(gameMatch.since).getTime()));
        movedEvents = false;
        // The round end of the game those events are from, as when SquadJS
        // restarted during the game while MySquadStats was down: the new
        // match saved after it, or the match of the game being played,
        // created after it ended, closes its match, the events are then tied
        // to it, and the round end then saves its result with them counted
        if (roundEndAfterMoved) {
          queue.push(request);
          continue;
        }
      }

      const retryResponse = await sendToAPI(
        request.method,
        request.dataType,
        data,
        accessToken
      );
      if (isMatchRequest && request.method === 'post') {
        replayedMatch = matchFrom(retryResponse);
        if (replayedMatch) newMatchAnswered = true;
      } else if (isMatchRequest && endsMatch(request.data, replayedMatch)) {
        replayedMatch = null;
      }
      if (onAnswer) onAnswer(request, retryResponse);
      if (retryResponse.status === 'Success') {
        remove();
        sent++;
        continue;
      }
      log(
        `Retry ${request.method.toUpperCase()} /${request.dataType} | ${retryResponse.status} | ${retryResponse.message}`
      );
      // A new match that gets no answer is kept the same way: sent again, it
      // gives the match it created, if it did, and after a restart it is the
      // only copy of the game's new match
      const newMatchNoAnswer =
        isMatchRequest && request.method === 'post' && retryResponse.noAnswer;
      // So is a moved event sent with no match that the API finds no match
      // for, with what was moved after it: its match can still be open, as
      // the API closes it only after answering the new match that closes it,
      // and a slow player list can hold that close up. Once one has been
      // dropped after RETRY_502_LIMIT of these answers, the ones moved after
      // it in the same pass are not kept: their match has not closed in that
      // time either, as when it was never created, and each would hold the
      // round end after them that long again.
      const movedRefused =
        !movedGivenUp &&
        index >= failedRequests.length &&
        noMatch &&
        typeof retryResponse.message === 'string' &&
        retryResponse.message.includes('No match found');
      if (
        retryResponse.httpStatus === 502 ||
        newMatchNoAnswer ||
        movedRefused
      ) {
        const count = (Number(request.count502) || 0) + 1;
        // MySquadStats answers pings but not this request, or still finds
        // no match for it: it is dropped, and the requests after it are sent
        if (count >= RETRY_502_LIMIT) {
          const others =
            isMatchRequest && request.method === 'post'
              ? ' or none'
              : movedRefused
                ? ' or refusals'
                : '';
          log(
            `Retry ${request.method.toUpperCase()} /${request.dataType} | Dropped after ${count} answers of 502${others}.`
          );
          if (movedRefused) movedGivenUp = true;
          remove();
          dropped++;
          continue;
        }
        // MySquadStats is down again, does not answer, or finds no match
        // yet: kept, with the requests after it
        changeSaved(request, (item) => ({ ...item, count502: count }));
        break;
      }
      if (request.retriesOnError > 1) {
        changeSaved(request, (item) => ({
          ...item,
          retriesOnError: request.retriesOnError - 1,
        }));
      } else {
        remove();
        dropped++;
      }
      // MySquadStats did not answer: the requests after it wait, except
      // after a round end, which the API can hold for a long time, as when
      // the server's player list is slow: the next game's new match is not
      // held up by it. The round end is kept for its next try as above, and
      // the API then finishes its match with it, even when the new match has
      // closed the match meanwhile.
      if (
        retryResponse.noAnswer &&
        !(isMatchRequest && request.method === 'patch')
      ) {
        break;
      }
    }
  } finally {
    removeDone();
  }

  const left = failedRequests.length - sent - dropped - skipped;
  return `Finished retrying failed requests: ${sent} sent, ${dropped} dropped, ${left} kept for later.${listsNote}`;
}

// Sends a request to the API. Returns its answer, or for a request that
// failed, an Error from handleApiError.
async function sendToAPI(method, dataType, data, accessToken) {
  try {
    const response = await axios({
      method: method,
      url: `https://api.mysquadstats.com/${dataType}`,
      data: data,
      params: { accessToken },
      timeout:
        dataType === 'admins' || (method === 'patch' && dataType === 'matches')
          ? ADMINS_API_TIMEOUT
          : API_TIMEOUT,
    });
    return response.data ?? '';
  } catch (error) {
    return handleApiError(error);
  }
}

// Sends a POST or PATCH request. When it gets a 502 (MySquadStats is down),
// it is saved to send again, unless saveForRetry is false. With
// retriesOnError, it is also saved when the API answers it with an Error or
// does not answer, and sent again that many times.
async function sendOrSave(method, dataType, data, accessToken, options) {
  const { saveForRetry = true, retriesOnError = 0 } = options || {};
  const response = await sendToAPI(method, dataType, data, accessToken);
  const answer =
    response && typeof response === 'object'
      ? response
      : { status: 'Error', message: 'The API answered with an empty body.' };
  if (
    answer.status === 'Success' ||
    !saveForRetry ||
    (answer.httpStatus !== 502 && !(retriesOnError > 0))
  ) {
    return answer;
  }
  // Save the request details to a local file for later retry
  try {
    const retryId = saveRetryRequest(
      method,
      dataType,
      data,
      retriesOnError,
      accessToken
    );
    return { ...answer, savedForRetry: true, retryId };
  } catch (error) {
    console.log(
      `MySquadStats | Could not save ${method.toUpperCase()} /${dataType} to send again: ${error.message}`
    );
    return answer;
  }
}

async function postDataToAPI(dataType, data, accessToken, options) {
  return sendOrSave('post', dataType, data, accessToken, options);
}

async function patchDataInAPI(dataType, data, accessToken, options) {
  return sendOrSave('patch', dataType, data, accessToken, options);
}

async function getDataFromAPI(dataType, accessToken) {
  return sendToAPI('get', dataType, undefined, accessToken);
}
